async function main() {
 const results=[];
 for(const [id,method,path] of [['GET 200','get','/request-sample.json'],['POST 200','post','/__test__/echo'],['404','get','/__missing__'],['429','get','/__test__/status?code=429'],['500','get','/__test__/status?code=500']]){
  try{const r=method==='post'?await axiosx.post('http://127.0.0.1:43111'+path,{hello:'Worker'},{timeout:5000}):await axiosx.get('http://127.0.0.1:43111'+path,{timeout:5000});results.push({id,status:r.status,data:r.data,headers:r.headers});}
